//! Exact request-authentication fixtures generated by the pinned TypeScript reference.
//!
//! Every `signature_base` in the fixture is the reference's own: the generator wraps the signer and
//! the verifier so the bytes each is handed are captured while the real primitive still runs. The
//! Rust tests therefore compare canonicalization directly, not only through the signature it
//! produces.

use std::error::Error;

use keri_cesr::crypto::salt::{Salt, SecurityTier};
use keri_cesr::crypto::verifier::{KeyTransferability, VerificationKey};
use serde::Deserialize;
use signify_http::header::{HeaderName, HeaderValue, Headers};
use signify_http::signature::authentication::{AuthenticationError, RequestSigner, ResponseVerifier};
use signify_http::signature::fields::{FieldText, SignatureHeader};
use signify_http::signature::input::{
    InputLabel, RequestTarget, SignatureComponent, SignatureInput, SignatureInputBuilder, SignatureInputError,
    SignatureInputHeader, default_components,
};

const REFERENCE_SHA: &str = "ae92eceb8e776ad57669707bff7f84db9390b711";

#[derive(Debug, Deserialize)]
struct Fixture {
    schema_version: u8,
    upstream: String,
    reference_sha: String,
    generated_on: String,
    sources: Vec<String>,
    clock: Clock,
    signer: SignerProvenance,
    header_names: HeaderNames,
    default_fields: Vec<String>,
    normalize_trims: Normalize,
    siginput_cases: Vec<SiginputCase>,
    authenticator_sign_cases: Vec<SignCase>,
    authenticator_verify_cases: Vec<VerifyCase>,
    desiginput_cases: Vec<DesiginputCase>,
    two_entry_dictionary: String,
    reference_quirks: Quirks,
}

#[derive(Debug, Deserialize)]
struct Clock {
    frozen_at: String,
    created: u64,
    note: String,
}

