fn fixture() -> Result<Fixture, Box<dyn Error>> {
    Ok(serde_json::from_str(include_str!(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../fixtures/http-authing/v1.json"
    )))?)
}

/// Rebuilds the signer the reference derived, from the same salt and default parameters.
fn derive_signer(provenance: &SignerProvenance) -> Result<RequestSigner, Box<dyn Error>> {
    assert_eq!(provenance.tier, "low");
    assert!(!provenance.temporary_profile, "the production profile is expected");
    assert!(provenance.transferable);
    let salt = Salt::from_raw(provenance.salt.as_bytes(), SecurityTier::Low)?;
    Ok(RequestSigner::new(
        salt.derive_signer(&provenance.path, KeyTransferability::Transferable)?,
    ))
}

fn headers(pairs: &[(String, String)]) -> Result<Headers, Box<dyn Error>> {
    let mut headers = Headers::new();
    for (name, value) in pairs {
        headers.insert(HeaderName::new(name.clone())?, HeaderValue::new(value)?)?;
    }
    Ok(headers)
}

fn components(names: &[String]) -> Result<Vec<SignatureComponent>, Box<dyn Error>> {
    names.iter().map(|name| Ok(SignatureComponent::new(name)?)).collect()
}

/// Rebuilds one recorded `siginput` call with the Rust builder.
fn rebuild(case: &SiginputCase) -> Result<SignatureInput, Box<dyn Error>> {
    let mut builder = SignatureInputBuilder::new(
        InputLabel::new(case.input.label.clone())?,
        components(&case.input.fields)?,
        // Every case is generated under the frozen clock.
        1_609_459_200,
    );
    if let Some(expires) = case.input.expires {
        builder = builder.expires(expires);
    }
    if let Some(nonce) = &case.input.nonce {
        builder = builder.nonce(FieldText::new(nonce.clone())?);
    }
    if let Some(keyid) = &case.input.keyid {
        builder = builder.key_identifier(FieldText::new(keyid.clone())?);
    }
    if let Some(context) = &case.input.context {
        builder = builder.context(FieldText::new(context.clone())?);
    }
    if let Some(algorithm) = &case.input.alg {
        builder = builder.algorithm(FieldText::new(algorithm.clone())?);
    }
    Ok(builder.build()?)
}

/// Asserts a parsed input matches what the reference recovered from the same bytes.
fn assert_reparsed(recorded: &Inputage, input: &SignatureInput, case: &str) {
    assert_eq!(recorded.name, input.label().as_str(), "case {case} label");
    let names: Vec<&str> = input.components().iter().map(SignatureComponent::as_str).collect();
    assert_eq!(recorded.fields, names, "case {case} covered list");
    assert_eq!(recorded.created, Some(input.created()), "case {case} created");
    assert_eq!(recorded.expires, input.expires(), "case {case} expires");
    assert_eq!(recorded.nonce.as_deref(), input.nonce(), "case {case} nonce");
    assert_eq!(recorded.keyid.as_deref(), input.key_identifier(), "case {case} keyid");
    assert_eq!(recorded.context.as_deref(), input.context(), "case {case} context");
    assert_eq!(recorded.alg.as_deref(), input.algorithm(), "case {case} alg");
}

#[test]
fn fixture_metadata_matches_the_pinned_reference() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.schema_version, 1);
    assert_eq!(fixture.upstream, "https://github.com/WebOfTrust/signify-ts.git");
    assert_eq!(fixture.reference_sha, REFERENCE_SHA);
    assert_ne!(fixture.generated_on, "");
    assert_eq!(
        fixture.sources,
        [
            "src/keri/core/httping.ts",
            "src/keri/core/authing.ts",
            "test/core/httping.test.ts",
            "test/core/authing.test.ts",
        ]
    );

    // The header names the reference exports are this module's constants.
    assert_eq!(fixture.header_names.signature_input, SignatureInputHeader::NAME);
    assert_eq!(fixture.header_names.signature, SignatureHeader::NAME);
    assert_eq!(fixture.header_names.signify_timestamp, "Signify-Timestamp");

    // `Authenticater.DefaultFields` is what `default_components` returns, in order.
    let defaults = default_components()?;
    let names: Vec<&str> = defaults.iter().map(SignatureComponent::as_str).collect();
    assert_eq!(fixture.default_fields, names);

    // `normalize` trims, which `HeaderValue` does at construction.
    assert_eq!(
        HeaderValue::new(&fixture.normalize_trims.input)?.as_str(),
        fixture.normalize_trims.output
    );

    assert_ne!(fixture.clock.note, "");
    assert_eq!(fixture.clock.frozen_at, "2021-01-01T00:00:00.000Z");
    assert_eq!(fixture.clock.created, 1_609_459_200);
    Ok(())
}

/// The salt derives the same key the reference signed with, before any header is built.
#[test]
fn the_recorded_signer_is_reproduced_from_its_salt() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let signer = derive_signer(&fixture.signer)?;
    assert_eq!(signer.key_identifier()?.as_str(), fixture.signer.verification_key);
    Ok(())
}

#[test]
fn every_signature_base_and_header_is_reproduced_byte_for_byte() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let signer = derive_signer(&fixture.signer)?;
    assert_eq!(fixture.siginput_cases.len(), 7);

    for case in &fixture.siginput_cases {
        assert!(!case.note.is_empty(), "case {} has no note", case.name);
        let input = rebuild(case)?;
        let target = RequestTarget::new(&case.input.method, &case.input.path)?;
        let message = headers(&case.input.headers)?;

        let base = input.signature_base(&target, &message)?;
        assert_eq!(base.as_str(), case.signature_base, "case {} base differs", case.name);

        let header = SignatureInputHeader::new(vec![input.clone()])?;
        assert_eq!(
            header.to_header_value()?,
            case.signature_input_header,
            "case {} header differs",
            case.name
        );

        // Signing the reproduced base with the reproduced key gives the reference's signature.
        let attached = signer.sign(&input, &target, &message)?;
        let signature = SignatureHeader::parse(attached.signature())?;
        assert!(
            signature
                .to_header_value()?
                .contains(&format!("\"{}\"", case.signature_qb64)),
            "case {} signature differs",
            case.name
        );

        // The same bytes parse back into the same value.
        let parsed = SignatureInputHeader::parse(&case.signature_input_header)?;
        assert_eq!(parsed, header, "case {} did not survive parsing", case.name);

        // Reverse direction: the reference read these exact bytes and recovered these fields.
        assert_eq!(case.reparsed.len(), 1, "case {}", case.name);
        for recorded in &case.reparsed {
            let input = parsed.find(input.label()).ok_or("no input")?;
            assert_reparsed(recorded, input, &case.name);
        }
    }
    Ok(())
}

#[test]
fn the_authenticator_reproduces_both_request_headers() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let signer = derive_signer(&fixture.signer)?;
    assert_eq!(fixture.authenticator_sign_cases.len(), 2);

    for case in &fixture.authenticator_sign_cases {
        assert!(!case.note.is_empty(), "case {} has no note", case.name);
        let covered = match &case.fields {
            Some(fields) => components(fields)?,
            None => default_components()?,
        };
        let input = signer.signature_input(covered, fixture.clock.created)?;
        let target = RequestTarget::new(&case.method, &case.path)?;
        let message = headers(&case.request_headers)?;

        assert_eq!(
            input.signature_base(&target, &message)?.as_str(),
            case.signature_base,
            "case {} base differs",
            case.name
        );

        let attached = signer.sign(&input, &target, &message)?;
        assert_eq!(
            attached.signature_input(),
            case.signature_input_header,
            "case {} input header differs",
            case.name
        );
        assert_eq!(
            attached.signature(),
            case.signature_header,
            "case {} signature header differs",
            case.name
        );
    }
    Ok(())
}

#[test]
fn the_authenticator_reproduces_response_verification() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.authenticator_verify_cases.len(), 3);

    for case in &fixture.authenticator_verify_cases {
        assert!(!case.note.is_empty(), "case {} has no note", case.name);
        let verifier = ResponseVerifier::new(VerificationKey::from_qb64(&case.verification_key)?);
        let target = RequestTarget::new(&case.method, &case.path)?;
        let message = headers(&case.response_headers)?;

        // The base the reference reconstructed is the base Rust reconstructs.
        let recorded_base = case.signature_base.as_deref().ok_or("no recorded base")?;
        let input_value = message.get("Signature-Input").ok_or("no signature input")?;
        let input = SignatureInputHeader::parse(input_value)?;
        let input = input.find(&InputLabel::signify()).ok_or("no signify input")?;
        assert_eq!(
            input.signature_base(&target, &message)?.as_str(),
            recorded_base,
            "case {} base differs",
            case.name
        );

        match verifier.verify(&target, &message) {
            Ok(input) => {
                assert_eq!(case.verified, Some(true), "case {} verified in Rust only", case.name);
                assert!(!case.threw, "case {}", case.name);
                assert_eq!(input.created(), 1_684_715_820);
                assert_eq!(
                    input.key_identifier(),
                    Some("EEXekkGu9IAzav6pZVJhkLnjtjM5v3AcyA-pdKUcaGei")
                );
            }
            Err(AuthenticationError::Verification { .. }) => {
                // The reference throws for exactly these, rather than returning false.
                assert!(case.threw, "case {} failed in Rust only", case.name);
                assert!(
                    case.error_message.as_ref().is_some_and(|text| text.contains("invalid")),
                    "case {}",
                    case.name
                );
            }
            Err(error) => return Err(format!("case {} failed unexpectedly: {error}", case.name).into()),
        }
    }
    Ok(())
}

#[test]
fn every_recorded_signature_input_parses_to_the_recorded_fields() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.desiginput_cases.len(), 3);

    for case in &fixture.desiginput_cases {
        assert!(!case.note.is_empty(), "case {} has no note", case.name);
        let header = SignatureInputHeader::parse(&case.value)?;
        assert_eq!(header.inputs().len(), case.parsed.len(), "case {}", case.name);
        for (recorded, input) in case.parsed.iter().zip(header.inputs()) {
            assert_reparsed(recorded, input, &case.name);
        }
        // Re-rendering gives back the exact bytes the reference emitted.
        assert_eq!(header.to_header_value()?, case.value, "case {}", case.name);
    }

    // Two members are separated by a comma and a space, which the reference's serializer decides.
    let two = SignatureInputHeader::parse(&fixture.two_entry_dictionary)?;
    assert_eq!(two.inputs().len(), 2);
    assert_eq!(two.to_header_value()?, fixture.two_entry_dictionary);
    Ok(())
}

/// The defects that change what a signature actually covers.
#[test]
fn reference_coverage_quirks_are_pinned_and_safely_diverged() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let quirks = &fixture.reference_quirks;
    let message = headers(&fixture.siginput_cases.first().ok_or("no case")?.input.headers.clone())?;

    // 1. `created` comes from the system clock.
    let clock = &quirks.created_defaults_to_the_system_clock;
    assert_eq!(clock.frozen_created, fixture.clock.created);
    assert_eq!(clock.frozen_at, fixture.clock.frozen_at);
    assert!(clock.note.contains("nowUTC"));
    assert!(clock.rust_decision.contains("required parameter"));

    // 2. An absent covered header is dropped from the signed list and from the base.
    let dropped = &quirks.an_absent_covered_header_is_dropped;
    assert!(
        !dropped.signing_base.contains("x-absent") && !dropped.signing_header.contains("x-absent"),
        "the component survived signing upstream"
    );
    // Verifying keeps the field listed while the item disappears, so the base matches no signer.
    assert!(dropped.verifying_fields.contains("x-absent"));
    assert!(dropped.verifying_base.contains("x-absent"));
    assert!(!dropped.verifying_base.contains("\"x-absent\": "));
    assert_eq!(dropped.rust_error_category, "MissingCoveredHeader");
    assert_ne!(dropped.note, "");
    let input = SignatureInputBuilder::new(
        InputLabel::signify(),
        vec![SignatureComponent::Method, SignatureComponent::new("x-absent")?],
        1,
    )
    .build()?;
    assert!(matches!(
        input.signature_base(&RequestTarget::new("GET", "/x")?, &message),
        Err(SignatureInputError::MissingCoveredHeader { .. })
    ));

    // 3. An unknown derived component is advertised and covers nothing.
    let derived = &quirks.an_unknown_derived_component_covers_nothing;
    assert!(!derived.signing_header.contains("@authority"));
    assert!(derived.verifying_base.contains("@authority"));
    assert!(!derived.verifying_base.contains("\"@authority\": "));
    assert!(derived.verifying_threw);
    assert!(!derived.signing_base.contains("@authority"));
    assert_eq!(derived.rust_error_category, "UnknownDerivedComponent");
    assert_ne!(derived.note, "");
    for name in ["@authority", "@query"] {
        assert!(matches!(
            SignatureComponent::new(name),
            Err(SignatureInputError::UnknownDerivedComponent { .. })
        ));
    }

    // 4. An empty covered list binds nothing at all.
    let empty = &quirks.an_empty_covered_list_is_accepted;
    assert!(empty.header.contains("signify=()"));
    assert!(empty.base.starts_with("\"@signature-params: ();"));
    assert_eq!(empty.rust_error_category.as_deref(), Some("NoComponents"));
    assert_ne!(empty.note, "");
    assert!(matches!(
        SignatureInputBuilder::new(InputLabel::signify(), Vec::new(), 1).build(),
        Err(SignatureInputError::NoComponents)
    ));

    // 5. A field name keeps its case in the base while lookup ignores it.
    let case_kept = &quirks.field_names_keep_their_case;
    assert!(case_kept.base.contains("\"SIGNIFY-RESOURCE\": "));
    assert!(case_kept.header.contains("\"SIGNIFY-RESOURCE\""));
    assert!(case_kept.note.contains("keripy"));
    assert!(case_kept.rust_decision.contains("verbatim"));
    let upper = SignatureInputBuilder::new(
        InputLabel::signify(),
        vec![SignatureComponent::new("SIGNIFY-RESOURCE")?],
        fixture.clock.created,
    )
    .key_identifier(FieldText::new(fixture.signer.verification_key.clone())?)
    .algorithm(FieldText::new("ed25519")?)
    .build()?;
    assert_eq!(
        upper
            .signature_base(&RequestTarget::new("GET", "/x")?, &message)?
            .as_str(),
        case_kept.base
    );

    // 6. A duplicated header is joined, silently changing the base.
    let joined = &quirks.duplicate_headers_are_joined;
    assert_eq!(joined.joined, "1, 2");
    assert_eq!(joined.rust_error_category, "DuplicateHeader");
    assert_ne!(joined.note, "");
    let mut duplicated = Headers::new();
    duplicated.insert(HeaderName::new("X-Repeat")?, HeaderValue::new("1")?)?;
    assert!(
        duplicated
            .insert(HeaderName::new("x-repeat")?, HeaderValue::new("2")?)
            .is_err()
    );
    Ok(())
}

/// The defects that let a caller forge material inside the signed bytes.
#[test]
fn reference_injection_quirks_are_pinned_and_safely_diverged() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let quirks = &fixture.reference_quirks;

    // 7. The header escapes a parameter value that the base interpolates raw, so the two disagree.
    let escaped = &quirks.a_parameter_is_escaped_in_the_header_but_not_in_the_base;
    assert!(escaped.base.contains("keyid=a\"b\\c"));
    assert!(escaped.header.contains("keyid=\"a\\\"b\\\\c\""));
    assert_eq!(escaped.rust_error_category.as_deref(), Some("InvalidFieldText"));
    assert_ne!(escaped.note, "");
    assert!(FieldText::new("a\"b\\c").is_err());

    // 8. A semicolon in a parameter value adds a parameter to the signed bytes only.
    let forged = &quirks.a_parameter_containing_a_semicolon_forges_a_parameter;
    assert!(forged.base.contains(";alg=forged;alg=ed25519"));
    assert!(forged.header.contains("keyid=\"a;alg=forged\""));
    assert_eq!(forged.rust_error_category.as_deref(), Some("InvalidFieldText"));
    assert_ne!(forged.note, "");
    assert!(FieldText::new("a;alg=forged").is_err());

    // 9. A newline in the path adds a whole forged component line.
    let path = &quirks.a_path_containing_a_newline_forges_a_line;
    assert!(path.base.contains("\"@method\": DELETE\n\"@method\": GET"));
    assert!(!path.header.contains("DELETE"), "the header hides the forged line");
    assert_eq!(path.rust_error_category.as_deref(), Some("InvalidRequestPath"));
    assert_ne!(path.note, "");
    assert!(matches!(
        RequestTarget::new("GET", "/a\n\"@method\": DELETE"),
        Err(SignatureInputError::InvalidRequestPath { .. })
    ));
    Ok(())
}

/// The parser and verifier defects, and the reference-rejected vectors.
#[test]
fn reference_parser_quirks_are_pinned_and_safely_diverged() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let quirks = &fixture.reference_quirks;

    // 10-11. Two inputs the reference itself rejects; Rust rejects them too, with typed errors.
    let created = &quirks.desiginput_requires_created;
    assert!(created.threw);
    assert_eq!(created.error_category.as_deref(), Some("Error"));
    assert!(
        created
            .error_message
            .as_ref()
            .is_some_and(|text| text.contains("created"))
    );
    assert_eq!(created.rust_error_category, "MissingCreated");
    assert!(matches!(
        SignatureInputHeader::parse("signify=(\"@method\");alg=\"ed25519\""),
        Err(SignatureInputError::MissingCreated { .. })
    ));

    let malformed = &quirks.desiginput_rejects_a_malformed_dictionary;
    assert!(malformed.threw);
    assert_eq!(malformed.error_category.as_deref(), Some("ParseError"));
    assert_eq!(malformed.rust_error_category, "MalformedSignatureInput");
    assert!(matches!(
        SignatureInputHeader::parse("signify=("),
        Err(SignatureInputError::Malformed { .. })
    ));
    assert!(!created.note.is_empty() && !malformed.note.is_empty());

    // 12. A duplicate label silently discards the earlier input.
    let duplicate = &quirks.a_duplicate_label_replaces_the_earlier_input;
    assert_eq!(duplicate.parsed.len(), 1, "upstream kept both inputs");
    assert_eq!(
        duplicate.parsed.first().and_then(|input| input.created),
        Some(2),
        "upstream kept the earlier input"
    );
    assert_eq!(duplicate.rust_error_category, "DuplicateLabel");
    assert_ne!(duplicate.note, "");
    assert!(matches!(
        SignatureInputHeader::parse("signify=(\"@method\");created=1, signify=(\"@path\");created=2"),
        Err(SignatureInputError::DuplicateLabel { .. })
    ));

    // 13. The verified label is hardcoded, so another label is reported unverified.
    let label = &quirks.verify_hardcodes_the_signify_label;
    assert!(!label.threw);
    assert_eq!(label.value, Some(false));
    assert!(label.rust_decision.contains("constructor parameter"));
    assert_ne!(label.note, "");

    // 14. Only the first signage is read.
    let first = &quirks.verify_reads_only_the_first_signage;
    assert!(first.threw);
    assert!(
        first
            .error_message
            .as_ref()
            .is_some_and(|text| text.contains("invalid"))
    );
    assert!(first.rust_decision.contains("every signage"));

    // 15. A missing header is `false` while a bad signature throws.
    let mixed = &quirks.verify_is_false_for_a_missing_header_and_throws_for_a_bad_signature;
    assert!(!mixed.missing_signature_input.threw);
    assert_eq!(mixed.missing_signature_input.value, Some(false));
    assert!(!mixed.missing_signature.threw);
    assert_eq!(mixed.missing_signature.value, Some(false));
    assert!(mixed.bad_signature.threw);
    assert!(mixed.rust_decision.contains("distinct variant"));
    assert_ne!(mixed.note, "");

    // Rust distinguishes all three.
    let verifier = ResponseVerifier::new(VerificationKey::from_qb64(
        "DMZh_y-H5C3cSbZZST-fqnsmdNTReZxIh0t2xSTOJQ8a",
    )?);
    let case = fixture.authenticator_verify_cases.first().ok_or("no verify case")?;
    let target = RequestTarget::new(&case.method, &case.path)?;
    let complete = headers(&case.response_headers)?;
    assert!(verifier.verify(&target, &complete).is_ok());

    for dropped in ["signature-input", "signature"] {
        let remaining: Vec<(String, String)> = case
            .response_headers
            .iter()
            .filter(|(name, _)| !name.eq_ignore_ascii_case(dropped))
            .cloned()
            .collect();
        let partial = headers(&remaining)?;
        let expected_missing = dropped == "signature-input";
        assert!(
            matches!(
                verifier.verify(&target, &partial),
                Err(AuthenticationError::MissingSignatureInput)
            ) == expected_missing,
            "{dropped} produced the wrong failure",
        );
    }
    Ok(())
}
